def pre(moves):
    if not isinstance(moves, list) or len(moves) > 6:
        return False
    for m in moves:
        if not -10 <= m <= 10:
            return False
    return True

def post(moves, result):
    if not isinstance(result, bool):
        return False
    balance = 0
    for i in range(min(5, len(moves))):
        balance += moves[i]
        if result and balance >= 0:
            return False
        elif not result and balance < 0:
            return False
    return True
